int Majority(const int A[], int n) {
    if (A == NULL || n <= 0) return -1;
    int candidate = 0, count = 0;
    for (int i = 0; i < n; ++i) {
        if (count == 0) { candidate = A[i]; count = 1; }
        else if (A[i] == candidate) ++count;
        else --count;
    }
    count = 0;
    for (int i = 0; i < n; ++i)
        if (A[i] == candidate) ++count;
    return count > n / 2 ? candidate : -1;
}

