    int data;
    struct node *link;
} NODE, *PNODE;

void delete_abs_duplicates(PNODE head, int n) {
    if (head == NULL || n < 0) return;
    unsigned char *seen = (unsigned char *)calloc((size_t)n + 1, 1);
    if (seen == NULL) return;
    PNODE p = head;
    while (p->link != NULL) {
        PNODE r = p->link;
        long long v = r->data < 0 ? -(long long)r->data : (long long)r->data;
        if (v <= n && !seen[v]) {
            seen[v] = 1;
            p = r;
        } else {
            p->link = r->link;
            free(r);
        }
    }
    free(seen);
}

