void reorder(NODE *head) {
    if (head == NULL || head->next == NULL || head->next->next == NULL) return;
    NODE *slow = head->next, *fast = head->next;
    while (fast->next != NULL && fast->next->next != NULL) {
        slow = slow->next;
        fast = fast->next->next;
    }
    NODE *cur = slow->next;
    slow->next = NULL;                 // 断开前后两段
    NODE *rev = NULL;
    while (cur != NULL) {              // 后半段原地逆置
        NODE *next = cur->next;
        cur->next = rev;
        rev = cur;
        cur = next;
    }
    NODE *first = head->next;
    while (rev != NULL) {              // 两段交替合并
        NODE *next1 = first->next;
        NODE *next2 = rev->next;
        first->next = rev;
        rev->next = next1;
        first = next1;
        rev = next2;
    }
}

