bool minPositiveDistance(const int A[], int n1,
                         const int B[], int n2,
                         const int C[], int n3,
                         long long *best, int *ra, int *rb, int *rc) {
    int i = 0, j = 0, k = 0;
    // 按原卷“a、b、c均为正数”的字面要求，跳过非正元素。
    while (i < n1 && A[i] <= 0) ++i;
    while (j < n2 && B[j] <= 0) ++j;
    while (k < n3 && C[k] <= 0) ++k;
    if (i == n1 || j == n2 || k == n3) return false;

    *best = LLONG_MAX;
    while (i < n1 && j < n2 && k < n3) {
        long long a = A[i], b = B[j], c = C[k];
        long long low = a, high = a;
        if (b < low) low = b; if (c < low) low = c;
        if (b > high) high = b; if (c > high) high = c;
        long long d = 2LL * (high - low);
        if (d < *best) {
            *best = d; *ra = (int)a; *rb = (int)b; *rc = (int)c;
        }
        if (*best == 0) break;
        if (a == low) ++i;
        else if (b == low) ++j;
        else ++k;
    }
    return true;
}

