typedef struct Trie {
    struct Trie *child[2];
    int symbol;              // -1表示非字符结点
} Trie;

bool insertCode(Trie *root, const char *code, int symbol) {
    Trie *p = root;
    for (int i = 0; code[i]; ++i) {
        if (p->symbol != -1) return false; // 旧编码是新编码前缀
        int bit = code[i] - '0';
        if (p->child[bit] == NULL) p->child[bit] = newNode();
        p = p->child[bit];
    }
    if (p->symbol != -1 || p->child[0] || p->child[1]) return false;
    p->symbol = symbol;
    return true;
}

// 无符号移位加法示意（n位结果按模2^n保留）
unsigned umul_shift_add(unsigned x, unsigned y) {
    unsigned result = 0;
    while (y != 0) {
        if (y & 1U) result += x;
        x <<= 1;
        y >>= 1;
    }
    return result;
}
