int uniquely(MGraph G) {
    int n = G.numVertices;
    int inDegree[MAXV] = {0};
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (G.Edge[i][j] != 0) ++inDegree[j];
    for (int k = 0; k < n; ++k) {
        int target = -1;
        for (int i = 0; i < n; ++i) {
            if (inDegree[i] == 0) {
                if (target != -1) return 0; // 本轮不唯一
                target = i;
            }
        }
        if (target == -1) return 0; // 有环
        inDegree[target] = -1;       // 标记删除
        for (int j = 0; j < n; ++j)
            if (G.Edge[target][j] != 0) --inDegree[j];
    }
    return 1;
}

