void calMulMax(int A[], int res[], int n) {
    if (n <= 0) return;
    int maxSuffix = A[n - 1];
    int minSuffix = A[n - 1];
    for (int i = n - 1; i >= 0; --i) {
        if (A[i] > maxSuffix) maxSuffix = A[i];
        if (A[i] < minSuffix) minSuffix = A[i];
        if (A[i] > 0)
            res[i] = A[i] * maxSuffix;
        else
            res[i] = A[i] * minSuffix;
    }
}

